from __future__ import annotations

import html
import json
from collections import defaultdict
from datetime import datetime, timezone
from pathlib import Path

from .config import PUBLIC_DIR

FOCUS=["DELITOS LEY DE DROGAS","DELITOS ECONÓMICOS Y TRIBUTARIOS","DELITOS FUNCIONARIOS"]
def _fmt(n): return f"{int(n):,}".replace(",",".") if n is not None else "—"
def _esc(x): return html.escape(str(x))

def build_dashboard(metrics:list[dict],risks:list[dict],source_status:list[dict],output:Path|None=None,events:list[dict]|None=None,region_priority:list[dict]|None=None,commune_priority:list[dict]|None=None,legal:dict|None=None,cead_catalog:dict|None=None,publications:list[dict]|None=None,integration:list[dict]|None=None,homicide_context:dict|None=None,cead_metrics:list[dict]|None=None)->Path:
    output=output or PUBLIC_DIR/"index.html"; events=events or []; region_priority=region_priority or []; commune_priority=commune_priority or []; legal=legal or {}; cead_catalog=cead_catalog or {}; publications=publications or []; integration=integration or []; homicide_context=homicide_context or {}; cead_metrics=cead_metrics or []
    mp_years=sorted({int(r["year"]) for r in metrics if r.get("metric")=="delitos_ingresados"}); latest=max(mp_years) if mp_years else None
    nat=defaultdict(int)
    for r in metrics:
        if r.get("territory_level")=="national" and r.get("metric")=="delitos_ingresados" and r.get("crime_category") in FOCUS: nat[(r["year"],r["crime_category"])]=r["value"]
    cead_communes=len({r["territory_id"] for r in cead_metrics if r.get("year")==2024 and r.get("cead_family_key")=="delitos_asociados_drogas" and r.get("quality_status")=="usable"})
    quarantined=sum(1 for r in cead_metrics if str(r.get("quality_status","")).startswith("quarantined"))
    cards=[("CEAD comunal",_fmt(cead_communes),"comunas con tasa anual 2024 · drogas"),("Familia directa art. 27","Ley 20.000","CEAD asociados a drogas · pondera AML"),("Fiscalía histórica",f"2020–{latest or 's/d'}","delitos ingresados SAF · nivel regional"),("Homicidios","0%","peso AML · solo contexto")]
    card_html="".join(f'<div class="card"><div class="kicker">{_esc(a)}</div><div class="value">{_esc(b)}</div><div class="sub">{_esc(c)}</div></div>' for a,b,c in cards)
    commune_rows="".join(f'<tr><td>{i}</td><td>{_esc(r["commune_name"])}</td><td>{_esc(r["region_name"])}</td><td class="num strong">{r["cead_aml_priority_score"]:.1f}</td><td class="num">{r["drug_complaint_rate_100k"]:.1f}</td><td class="num">{_fmt(r.get("estimated_drug_complaints"))}</td><td><span class="pill {r["priority_level"]}">{r["priority_level"].replace("_"," ")}</span></td></tr>' for i,r in enumerate(commune_priority[:30],1)) or '<tr><td colspan="7">Sin datos CEAD comunales utilizables.</td></tr>'
    region_rows="".join(f'<tr><td>{i}</td><td>{_esc(r["region_name"])}</td><td class="num strong">{r["pressure_score"]:.1f}</td><td class="num">{r["aml_component_percentile"]:.1f}</td><td class="num">{r["trend_component"]:.1f}</td><td><span class="pill {r["pressure_level"]}">{r["pressure_level"].replace("_"," ")}</span></td></tr>' for i,r in enumerate(region_priority,1)) or '<tr><td colspan="6">Sin datos.</td></tr>'
    catalog_rows=""
    for key,c in (cead_catalog.get("families") or {}).items():
        eligible="Sí" if c.get("score_eligible") else "No"; catalog_rows+=f'<tr><td>{_esc(c.get("label",key))}</td><td>{_esc(c.get("article27_relation"))}</td><td>{eligible}</td><td class="num">{float(c.get("aml_weight",0)):.1f}</td><td>{_esc(c.get("legal_basis",""))}</td></tr>'
    trend_rows=""
    for year in mp_years: trend_rows+=f'<tr><td>{year}</td>'+''.join(f'<td class="num">{_fmt(nat.get((year,c),0))}</td>' for c in FOCUS)+'</tr>'
    def event_key(e): return (e.get("published_date") or "",e.get("retrieved_at") or "")
    recent=sorted(events,key=event_key,reverse=True)[:8]; event_rows="".join(f'<tr><td>{_esc(e.get("published_date") or "s/f")}</td><td><a href="{_esc(e.get("url",""))}" target="_blank" rel="noopener">{_esc(e.get("title",""))}</a></td><td>{_esc(", ".join(e.get("matched_keywords",[])[:3]))}</td></tr>' for e in recent) or '<tr><td colspan="3">Sin señales.</td></tr>'
    ok=sum(1 for s in source_status if isinstance(s,dict) and s.get("ok")); fail=sum(1 for s in source_status if isinstance(s,dict) and s.get("ok") is False)
    health_rows="".join(f'<tr><td>{_esc(s.get("source_id",""))}</td><td><span class="health {"ok" if s.get("ok") else "bad"}">{"OK" if s.get("ok") else "FALLA"}</span></td><td>{_esc(s.get("note") or s.get("fallback") or s.get("error","")[:130])}</td></tr>' for s in source_status[-18:])
    generated=datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC"); payload={"version":"0.3.0","cead_commune_priority":commune_priority,"region_mp_proxy":region_priority,"cead_catalog_art27":cead_catalog,"homicide_context":homicide_context,"cead_quarantined_records":quarantined,"source_status":source_status,"recent_events":recent,"integration":integration}
    (PUBLIC_DIR/"data.json").write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding="utf-8")
    doc=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Radar Delictual v0.3</title><style>:root{{--bg:#0e1116;--panel:#171b22;--line:#29303a;--text:#f4f5f7;--muted:#9aa3ae;--accent:#f28c28;--accent2:#ffb361;--good:#58c68b;--bad:#ef6b66}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 Inter,system-ui,-apple-system,Segoe UI,sans-serif}}.wrap{{max-width:1480px;margin:auto;padding:26px}}header{{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;margin-bottom:18px}}h1{{margin:0;font-size:31px;letter-spacing:-.7px}}h2{{font-size:16px;margin:0 0 12px}}.tag{{color:var(--accent);font-weight:850;text-transform:uppercase;letter-spacing:.13em;font-size:11px}}.desc{{color:var(--muted);max-width:900px;margin:6px 0 0}}.status{{text-align:right;color:var(--muted);font-size:12px}}.grid4{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}}.two{{display:grid;grid-template-columns:1.25fr .75fr;gap:14px;margin-top:14px}}.card,.panel{{background:var(--panel);border:1px solid var(--line);border-radius:15px}}.card{{padding:17px}}.panel{{padding:17px;overflow:auto}}.kicker{{color:var(--muted);font-size:11px;text-transform:uppercase;min-height:30px}}.value{{font-size:27px;font-weight:850}}.sub{{color:var(--muted);font-size:11px}}table{{width:100%;border-collapse:collapse;white-space:nowrap}}th,td{{padding:8px;border-bottom:1px solid var(--line);text-align:left}}th{{color:var(--muted);font-size:10px;text-transform:uppercase}}.num{{text-align:right;font-variant-numeric:tabular-nums}}.strong{{font-weight:800;color:var(--accent2)}}.pill{{font-size:10px;padding:4px 7px;border-radius:20px;border:1px solid var(--line)}}.muy_alta{{border-color:#f06e4d}}.alta{{border-color:#e7a348}}.media{{border-color:#a99967}}.note{{margin-top:14px;padding:13px 15px;border-left:3px solid var(--accent);background:#14181e;color:#c7cbd1;border-radius:8px}}.context{{border-left-color:#6b7280}}.health{{font-size:10px;font-weight:800}}.health.ok{{color:var(--good)}}.health.bad{{color:var(--bad)}}a{{color:var(--accent2)}}footer{{color:var(--muted);font-size:11px;margin-top:18px}}@media(max-width:950px){{.grid4{{grid-template-columns:1fr 1fr}}.two{{grid-template-columns:1fr}}header{{display:block}}.status{{text-align:left;margin-top:9px}}}}@media(max-width:550px){{.grid4{{grid-template-columns:1fr}}.wrap{{padding:14px}}}}</style></head><body><div class="wrap"><header><div><div class="tag">OSINT · AML · Chile · v0.3</div><h1>Radar Delictual</h1><p class="desc">La capa AML territorial prioriza delitos con vínculo jurídico defendible con el artículo 27 de la Ley 19.913. CEAD aporta granularidad comunal; homicidios y criminalidad general permanecen como contexto sin ponderación AML.</p></div><div class="status">CEAD comunas 2024: <b>{cead_communes}</b><br>2025 en cuarentena: <b>{quarantined}</b> registros<br>Fuentes OK {ok} · fallidas {fail}<br>{generated}</div></header><div class="grid4">{card_html}</div><section class="panel" style="margin-top:14px"><h2>Prioridad comunal CEAD · familia drogas vinculada a Ley 20.000</h2><table><thead><tr><th>#</th><th>Comuna</th><th>Región</th><th>Score</th><th>Tasa denuncias 2024</th><th>Frecuencia estimada</th><th>Nivel</th></tr></thead><tbody>{commune_rows}</tbody></table><div class="note">El score v0.3 usa únicamente la familia CEAD “Asociados a Drogas”, por su relación directa a nivel de familia con Ley 20.000. La frecuencia se deriva de tasa publicada y población cuando está disponible. No representa probabilidad de LA/FT.</div></section><div class="two"><section class="panel"><h2>Proxy regional · Ministerio Público · sin homicidios</h2><table><thead><tr><th>#</th><th>Región</th><th>Score</th><th>Componente AML</th><th>Tendencia</th><th>Nivel</th></tr></thead><tbody>{region_rows}</tbody></table></section><section class="panel"><h2>Serie Fiscalía</h2><table><thead><tr><th>Año</th><th>Drogas</th><th>Econ./trib.</th><th>Funcionarios</th></tr></thead><tbody>{trend_rows}</tbody></table><div class="note">Unidad: delitos ingresados a SAF. Homicidios tienen peso AML 0.</div></section></div><section class="panel" style="margin-top:14px"><h2>Catálogo CEAD ↔ artículo 27</h2><table><thead><tr><th>Familia</th><th>Relación art. 27</th><th>Pondera</th><th>Peso</th><th>Fundamento</th></tr></thead><tbody>{catalog_rows}</tbody></table></section><div class="two"><section class="panel"><h2>Control de calidad CEAD 2025</h2><p>Registros en cuarentena: <b>{quarantined}</b>.</p><div class="note">Los reportes 2026 son auditados sección por sección. Cuando “Drogas” reproduce exactamente los valores de otra familia, el registro se conserva como evidencia pero queda excluido del score hasta validación.</div></section><section class="panel"><h2>Homicidios · contexto</h2><p>Peso AML: <b>0,0</b> · Score elegible: <b>No</b></p><div class="note context">Se mantienen para caracterización del entorno delictual, pero no se interpretan como delito base, indicio de LA/FT ni componente del ranking AML.</div></section></div><section class="panel" style="margin-top:14px"><h2>Salud de fuentes</h2><table><thead><tr><th>Fuente</th><th>Estado</th><th>Detalle</th></tr></thead><tbody>{health_rows}</tbody></table></section><section class="panel" style="margin-top:14px"><h2>Señales OSINT oficiales recientes</h2><table><thead><tr><th>Fecha</th><th>Publicación</th><th>Fenómenos</th></tr></thead><tbody>{event_rows}</tbody></table></section><div class="note"><b>Interpretación:</b> una mayor incidencia territorial de delitos base no permite concluir que personas o actividades económicas ubicadas en el territorio participen en LA/FT. El radar prioriza investigación y cruces posteriores, preservando fuente, unidad de observación y calidad del dato.</div><footer>Radar Delictual v0.3 · CEAD comunal + artículo 27 · homicidios fuera del scoring AML.</footer></div></body></html>'''
    output.write_text(doc,encoding="utf-8"); return output
